CAT = "corrWriting"; SEG = "WRT"
# Preparing written material: restating information clearly and accurately, ordering a
# paragraph, and the grammar, spelling and punctuation of logs and reports.
# Paragraph organization. para() numbers the sentences in the order given by `labels`
# (labels[i] is the number shown for the i-th sentence of the correct paragraph) and lists them
# by number, so the key is the labels read in correct order.
def para(sents, labels, wrongs, expl):
    shown = sorted(zip(labels, sents))
    stem = "Put the sentences in the best order: " + " ".join(f"{n}. {t}" for n, t in shown) + " Which order is best?"
    fmt = lambda seq: ", ".join(str(labels[i]) for i in seq)
    return (stem, fmt(range(4)), [fmt(w) for w in wrongs], expl)

